@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold">Warehouse:</label>
    <select class="form-select form-select-sm" style="width: auto;"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in Services.WarehouseState.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString() ?? "";
        var warehouse = Services.WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == newId);

        if (warehouse != default)
        {
            WarehouseState.SetWarehouse(warehouse.Id, warehouse.Name);
            // Refresh alerts for the newly selected warehouse
            await AlertService.RefreshAsync();
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@inject Services.InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentLowStockCount > 0)
{
    <span class="badge bg-danger ms-2">@AlertService.CurrentLowStockCount</span>
}
else
{
    <span class="badge bg-success ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Use InvokeAsync because alerts fire from a timer (non-Blazor thread)
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertUpdated += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnAlertUpdated -= _handler;
    }
}

