@page "/dashboard"
@attribute [StreamRendering]
@rendermode InteractiveServer
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text display-4">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="text-muted">
                    Items below minimum level. Refreshes every 10 seconds.
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="card-text display-6">@WarehouseState.SelectedWarehouseName</p>
                <p class="text-muted">Change via the dropdown in the top bar.</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-success">Active</span>
                </p>
                <p class="text-muted">Polling starts when this page loads and stops when you navigate away.</p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to alert updates (fires from timer — use InvokeAsync)
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertUpdated += _alertHandler;

        // Subscribe to warehouse changes (fires from Blazor sync context)
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling — stops when this component is disposed (page navigated away)
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertUpdated -= _alertHandler;

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

